  const nice = trimmed.charAt(0).toUpperCase() + trimmed.slice(1).toLowerCase();
  const shout = trimmed.toUpperCase();
  const trimmedLength = trimmed.length;
  return `Hello, ${nice}! You have ${itemCount} item(s) in your cart. Your name has ${trimmedLength} characters. Order confirmed for ${shout}.`;
}

