function celsiusToFahrenheit(celsius) {
  return celsius * 9 / 5 + 32;
}

function classifyTemperature(celsiusValue) {
  if (celsiusValue <= 0) return "Freezing";
  if (celsiusValue <= 15) return "Cold";
  if (celsiusValue <= 25) return "Mild";
  return "Hot";
}

function describeWeather(celsiusValue) {
  const fahrenheit = celsiusToFahrenheit(celsiusValue);
  const category = classifyTemperature(celsiusValue);
  return `${celsiusValue}C (${fahrenheit}F) is classified as ${category}.`;
}

console.log(describeWeather(-5));

