solutionCodeJson.code:
function round2(value) {
  return Math.round(value * 100) / 100;
}

function formatReceipt(items, taxRate, discountCode) {
  const lines = [];
  let rawSubtotal = 0;

  for (const item of items) {
    const price = Number(item.priceInput);
    const quantity = Number(item.quantityInput);
    const lineTotal = round2(price * quantity);
    lines.push(`- ${item.name}: ${quantity} x $${price.toFixed(2)} = $${lineTotal.toFixed(2)}`);
    rawSubtotal += lineTotal;
  }

  const subtotal = round2(rawSubtotal);
  const discountAmount = discountCode === "SAVE10" ? round2(subtotal * 0.10) : 0;
  const discountedSubtotal = round2(subtotal - discountAmount);
  const tax = round2(discountedSubtotal * taxRate);
  const total = round2(discountedSubtotal + tax);

  return { lines, subtotal, discountAmount, tax, total };
}

const cart = [
  { name: "Notebook", priceInput: "4.5", quantityInput: "2" },
  { name: "Pen", priceInput: "1.25", quantityInput: 4 },
  { name: "Backpack", priceInput: "29.99", quantityInput: "1" }
];

console.log(JSON.stringify(formatReceipt(cart, 0.08, "SAVE10")));
